package com.example.pulsedialer;

import android.Manifest;
import android.content.pm.PackageManager;
import android.content.res.ColorStateList;
import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.content.Intent;
import android.net.Uri;
import android.os.Bundle;
import android.telecom.PhoneAccountHandle;
import android.telecom.TelecomManager;
import android.text.Editable;
import android.text.TextWatcher;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.EditText;
import android.widget.LinearLayout;
import android.widget.ImageView;
import android.widget.TextView;
import android.widget.Toast;
import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import androidx.appcompat.app.AlertDialog;
import androidx.core.content.ContextCompat;
import androidx.fragment.app.Fragment;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;
import com.google.android.material.button.MaterialButton;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class ListFragment extends Fragment {
    private static final ExecutorService WORKER=Executors.newSingleThreadExecutor();
    private int tab; private boolean firstResume=true; private String filter="All"; private List<ContactRepository.Contact> contacts=new ArrayList<>(); private List<ContactRepository.Recent> recents=new ArrayList<>(); private RowAdapter adapter; private EditText search; private TextView message; private RecyclerView list; private LinearLayout filters,alphaIndex;
    static ListFragment newInstance(int tab){ListFragment f=new ListFragment();Bundle b=new Bundle();b.putInt("tab",tab);f.setArguments(b);return f;}
    @Override public void onCreate(Bundle b){super.onCreate(b);tab=getArguments()==null?R.id.nav_recents:getArguments().getInt("tab",R.id.nav_recents);}
    @Nullable @Override public View onCreateView(@NonNull LayoutInflater i,@Nullable ViewGroup p,Bundle b){return i.inflate(R.layout.fragment_list,p,false);}
    @Override public void onViewCreated(@NonNull View v,Bundle b){super.onViewCreated(v,b);search=v.findViewById(R.id.search);message=v.findViewById(R.id.message);list=v.findViewById(R.id.list);filters=v.findViewById(R.id.filters);alphaIndex=v.findViewById(R.id.alpha_index);list.setLayoutManager(new LinearLayoutManager(requireContext()));adapter=new RowAdapter();list.setAdapter(adapter);
        if(tab==R.id.nav_sim){search.setVisibility(View.GONE);filters.setVisibility(View.GONE);if(!MainActivity.hasPermission(requireContext(),Manifest.permission.READ_PHONE_STATE)){showMessage(R.string.sim_permission,R.string.grant_permission);return;}loadAccounts();return;}
        search.setHint(tab==R.id.nav_contacts?R.string.search_contacts:R.string.search_calls);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){render();}public void afterTextChanged(Editable e){}});
        if(tab==R.id.nav_recents){buildFilters();if(!MainActivity.isDefaultDialer(requireContext())){showMessage(R.string.calls_role_required,R.string.make_default);return;}if(!MainActivity.hasPermission(requireContext(),Manifest.permission.READ_CALL_LOG)){showMessage(R.string.permission_calls,R.string.grant_permission);return;}}else{buildAlphaIndex();}
        if(tab==R.id.nav_contacts&&!MainActivity.hasPermission(requireContext(),Manifest.permission.READ_CONTACTS)){showMessage(R.string.permission_contacts,R.string.grant_permission);return;}
        loadData();
    }
    private int accent(){return requireActivity().getPreferences(0).getInt("accent",0xFF3B82F6);}
    private void showMessage(int text,int button){message.setVisibility(View.VISIBLE);message.setText(text);MaterialButton action=new MaterialButton(requireContext());action.setText(button);action.setBackgroundTintList(ColorStateList.valueOf(accent()));((ViewGroup)message.getParent()).addView(action,1);action.setOnClickListener(x->{if(tab==R.id.nav_sim)((MainActivity)requireActivity()).requestPhoneStateAccess();else if(tab==R.id.nav_contacts)((MainActivity)requireActivity()).requestContactAccess();else ((MainActivity)requireActivity()).requestCallLogAccess();});}
    private void buildFilters(){String[] labels={"All","Missed","Incoming","Outgoing","Rejected"};for(String label:labels){MaterialButton b=new MaterialButton(requireContext(),null,com.google.android.material.R.attr.materialButtonOutlinedStyle);b.setText(label);b.setTextColor(accent());b.setStrokeColor(ColorStateList.valueOf(accent()));b.setMinWidth(0);b.setOnClickListener(x->{filter=label;for(int i=0;i<filters.getChildCount();i++){MaterialButton q=(MaterialButton)filters.getChildAt(i);q.setSelected(q.getText().equals(filter));}render();});filters.addView(b);}}
    private void buildAlphaIndex(){alphaIndex.setVisibility(View.VISIBLE);for(char letter='A';letter<='Z';letter++){TextView label=new TextView(requireContext());label.setText(String.valueOf(letter));label.setTextSize(10);label.setTextColor(accent());label.setGravity(android.view.Gravity.CENTER);label.setMinHeight(dp(15));label.setContentDescription(getString(R.string.jump_to_letter,letter));label.setOnClickListener(x->jumpToLetter(label.getText().charAt(0)));alphaIndex.addView(label,new LinearLayout.LayoutParams(dp(24),dp(15)));}}
    private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
    private void jumpToLetter(char target){for(int i=0;i<adapter.rows.size();i++){Object row=adapter.rows.get(i);if(row instanceof ContactRepository.Contact){String name=((ContactRepository.Contact)row).name;if(name!=null&&!name.isEmpty()&&Character.toUpperCase(name.charAt(0))>=target){list.scrollToPosition(i);return;}}}if(adapter.getItemCount()>0)list.scrollToPosition(adapter.getItemCount()-1);}
    private void loadData(){if(tab==R.id.nav_contacts){message.setText(R.string.loading);message.setVisibility(View.VISIBLE);WORKER.execute(()->{List<ContactRepository.Contact> result=ContactRepository.contacts(requireContext().getApplicationContext());if(getActivity()!=null)getActivity().runOnUiThread(()->{contacts=result;message.setVisibility(View.GONE);render();});});}else{message.setText(R.string.loading);message.setVisibility(View.VISIBLE);WORKER.execute(()->{List<ContactRepository.Recent> result=ContactRepository.recents(requireContext().getApplicationContext());if(getActivity()!=null)getActivity().runOnUiThread(()->{recents=result;message.setVisibility(View.GONE);render();});});}}
    @Override public void onResume(){super.onResume();if(firstResume){firstResume=false;return;}if(adapter!=null){if(tab==R.id.nav_contacts&&MainActivity.hasPermission(requireContext(),Manifest.permission.READ_CONTACTS))loadData();if(tab==R.id.nav_recents&&MainActivity.isDefaultDialer(requireContext())&&MainActivity.hasPermission(requireContext(),Manifest.permission.READ_CALL_LOG))loadData();if(tab==R.id.nav_sim&&MainActivity.hasPermission(requireContext(),Manifest.permission.READ_PHONE_STATE))loadAccounts();}}
    private void render(){if(adapter==null)return;adapter.rows.clear();String q=search==null?"":search.getText().toString().trim().toLowerCase(Locale.getDefault());if(tab==R.id.nav_contacts){List<ContactRepository.Contact> result=new ArrayList<>();for(ContactRepository.Contact c:contacts)if(q.isEmpty()||(c.name!=null&&c.name.toLowerCase(Locale.getDefault()).contains(q))||(c.number!=null&&c.number.toLowerCase(Locale.getDefault()).contains(q)))result.add(c);java.text.Collator collator=java.text.Collator.getInstance();Collections.sort(result,(a,b)->{int favorite=Boolean.compare(b.starred,a.starred);if(favorite!=0)return favorite;return collator.compare(a.name==null?"":a.name,b.name==null?"":b.name);});adapter.rows.addAll(result);}else{for(ContactRepository.Recent c:recents){if(!filter.equals("All")&&!filter.equals(c.kind()))continue;String name=c.name==null||c.name.trim().isEmpty()?c.number:c.name;if(q.isEmpty()||(name!=null&&name.toLowerCase(Locale.getDefault()).contains(q))||(c.number!=null&&c.number.toLowerCase(Locale.getDefault()).contains(q)))adapter.rows.add(c);}}adapter.notifyDataSetChanged();if(adapter.getItemCount()==0&&message.getVisibility()!=View.VISIBLE){message.setVisibility(View.VISIBLE);message.setText(q.isEmpty()?(tab==R.id.nav_contacts?R.string.empty_contacts:R.string.empty_recents):R.string.no_results);}else if(adapter.getItemCount()>0)message.setVisibility(View.GONE);}
    private void loadAccounts(){if(ContextCompat.checkSelfPermission(requireContext(),Manifest.permission.READ_PHONE_STATE)!=PackageManager.PERMISSION_GRANTED){message.setText(R.string.sim_permission);return;}TelecomManager tm=(TelecomManager)requireContext().getSystemService(android.content.Context.TELECOM_SERVICE);if(tm==null){message.setText(R.string.no_telecom);return;}try{List<PhoneAccountHandle> accounts=tm.getCallCapablePhoneAccounts();if(accounts==null||accounts.isEmpty()){message.setText(R.string.no_sim_accounts);return;}StringBuilder out=new StringBuilder(getString(R.string.accounts_heading));for(int i=0;i<accounts.size();i++){PhoneAccountHandle h=accounts.get(i);android.telecom.PhoneAccount a=tm.getPhoneAccount(h);out.append("\n\n").append(a==null?getString(R.string.call_account_label,i+1):a.getLabel()).append("\n").append(a==null?"":a.getShortDescription());}out.append("\n\n").append(getString(R.string.sim_contacts_limited));message.setText(out);message.setVisibility(View.VISIBLE);}catch(SecurityException e){message.setText(R.string.no_sim_accounts);}}
    private void rowAction(Object row){if(row instanceof ContactRepository.Contact){ContactRepository.Contact c=(ContactRepository.Contact)row;String[] actions={getString(R.string.call),getString(R.string.message_action),getString(R.string.details),getString(c.starred?R.string.remove_favorite:R.string.add_favorite),getString(R.string.edit),getString(R.string.share),getString(R.string.delete)};new AlertDialog.Builder(requireContext()).setTitle(c.name).setItems(actions,(d,w)->{if(w==0)((MainActivity)requireActivity()).openDialpad(c.number);else if(w==1)message(c.number);else if(w==2)contactDetails(c);else if(w==3)favorite(c);else if(w==4)edit(c);else if(w==5)share(c);else delete(c);}).show();}else if(row instanceof ContactRepository.Recent){ContactRepository.Recent c=(ContactRepository.Recent)row;String[] actions={getString(R.string.call_back),getString(R.string.details),getString(R.string.message_action),getString(R.string.add_contact)};new AlertDialog.Builder(requireContext()).setTitle(c.name==null?c.number:c.name).setItems(actions,(d,w)->{if(w==0)((MainActivity)requireActivity()).openDialpad(c.number);else if(w==1)new AlertDialog.Builder(requireContext()).setTitle(R.string.call_details).setMessage((c.name==null?getString(R.string.unknown_number):c.name)+"\n"+c.number+"\n"+c.kind()+"\n"+ContactRepository.dateLabel(c.date)+"\n"+getString(R.string.duration_label,ContactRepository.duration(c.duration))+(c.account==null?"":"\n"+c.account)).setPositiveButton(android.R.string.ok,null).show();else if(w==2)message(c.number);else addContact(c.number);}).show();}}
    private void contactDetails(ContactRepository.Contact c){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.withAppendedPath(android.provider.ContactsContract.Contacts.CONTENT_URI,String.valueOf(c.id))));}catch(Exception e){new AlertDialog.Builder(requireContext()).setTitle(c.name).setMessage(c.number==null?getString(R.string.no_phone):c.number).setPositiveButton(R.string.call,(d,w)->((MainActivity)requireActivity()).openDialpad(c.number)).setNeutralButton(R.string.message_action,(d,w)->message(c.number)).setNegativeButton(android.R.string.cancel,null).show();}}
    private void message(String n){try{startActivity(new Intent(Intent.ACTION_SENDTO,Uri.parse("smsto:"+Uri.encode(n==null?"":n))));}catch(Exception e){Toast.makeText(requireContext(),R.string.action_unavailable,Toast.LENGTH_SHORT).show();}}
    private void edit(ContactRepository.Contact c){try{startActivity(new Intent(Intent.ACTION_EDIT,Uri.withAppendedPath(android.provider.ContactsContract.Contacts.CONTENT_URI,String.valueOf(c.id))));}catch(Exception e){Toast.makeText(requireContext(),R.string.action_unavailable,Toast.LENGTH_SHORT).show();}}
    private void addContact(String n){try{Intent i=new Intent(Intent.ACTION_INSERT,android.provider.ContactsContract.Contacts.CONTENT_URI);i.putExtra(android.provider.ContactsContract.Intents.Insert.PHONE,n);startActivity(i);}catch(Exception e){Toast.makeText(requireContext(),R.string.action_unavailable,Toast.LENGTH_SHORT).show();}}
    private void share(ContactRepository.Contact c){try{Uri vcard=Uri.withAppendedPath(android.provider.ContactsContract.Contacts.CONTENT_VCARD_URI,String.valueOf(c.id));Intent intent=new Intent(Intent.ACTION_SEND).setType("text/vcard").putExtra(Intent.EXTRA_STREAM,vcard).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(intent,getString(R.string.share)));}catch(Exception e){Toast.makeText(requireContext(),R.string.action_unavailable,Toast.LENGTH_SHORT).show();}}
    private void delete(ContactRepository.Contact c){if(!MainActivity.hasPermission(requireContext(),Manifest.permission.WRITE_CONTACTS)){new AlertDialog.Builder(requireContext()).setMessage(R.string.favorite_permission).setPositiveButton(R.string.grant_permission,(d,w)->((MainActivity)requireActivity()).requestContactWriteAccess()).setNegativeButton(android.R.string.cancel,null).show();return;}new AlertDialog.Builder(requireContext()).setTitle(R.string.delete_contact).setMessage(getString(R.string.delete_confirmation,c.name==null?"":c.name)).setNegativeButton(android.R.string.cancel,null).setPositiveButton(R.string.delete,(d,w)->{android.content.Context app=requireContext().getApplicationContext();WORKER.execute(()->{int count=0;try{count=app.getContentResolver().delete(Uri.withAppendedPath(android.provider.ContactsContract.Contacts.CONTENT_URI,String.valueOf(c.id)),null,null);}catch(SecurityException ignored){}int deleted=count;if(getActivity()!=null)getActivity().runOnUiThread(()->{Toast.makeText(requireContext(),deleted>0?R.string.contact_deleted:R.string.contact_delete_failed,Toast.LENGTH_SHORT).show();loadData();});});}).show();}
    private void favorite(ContactRepository.Contact c){if(!MainActivity.hasPermission(requireContext(),Manifest.permission.WRITE_CONTACTS)){new AlertDialog.Builder(requireContext()).setMessage(R.string.favorite_permission).setPositiveButton(R.string.grant_permission,(d,w)->((MainActivity)requireActivity()).requestContactWriteAccess()).setNegativeButton(android.R.string.cancel,null).show();return;}android.content.ContentValues v=new android.content.ContentValues();v.put(android.provider.ContactsContract.Contacts.STARRED,c.starred?0:1);android.content.Context app=requireContext().getApplicationContext();WORKER.execute(()->{try{app.getContentResolver().update(Uri.withAppendedPath(android.provider.ContactsContract.Contacts.CONTENT_URI,String.valueOf(c.id)),v,null,null);if(getActivity()!=null)getActivity().runOnUiThread(this::loadData);}catch(SecurityException ignored){}});}
    private static class RowAdapter extends RecyclerView.Adapter<RowHolder>{final List<Object> rows=new ArrayList<>();@NonNull public RowHolder onCreateViewHolder(@NonNull ViewGroup p,int t){return new RowHolder(LayoutInflater.from(p.getContext()).inflate(R.layout.item_contact,p,false));}public void onBindViewHolder(@NonNull RowHolder h,int i){Object row=rows.get(i);android.content.Context context=h.itemView.getContext();boolean compact=context.getSharedPreferences("MainActivity",0).getBoolean("compact",false);int vertical=(int)((compact?5:10)*context.getResources().getDisplayMetrics().density);h.itemView.setPadding(h.itemView.getPaddingLeft(),vertical,h.itemView.getPaddingRight(),vertical);h.photo.setTag(null);if(row instanceof ContactRepository.Contact){ContactRepository.Contact c=(ContactRepository.Contact)row;h.name.setText((c.starred?"★  ":"")+(c.name==null||c.name.isEmpty()?context.getString(R.string.unknown_contact):c.name));h.detail.setText(c.number==null?context.getString(R.string.no_phone):c.number);h.avatar.setText(initials(c.name));h.photo.setImageDrawable(null);h.photo.setVisibility(View.GONE);if(c.photo!=null){h.photo.setTag(c.photo.toString());WORKER.execute(()->{Bitmap image=null;try(java.io.InputStream in=context.getContentResolver().openInputStream(c.photo)){if(in!=null)image=BitmapFactory.decodeStream(in);}catch(Exception ignored){}Bitmap result=image;if(result!=null)h.itemView.post(()->{if(c.photo.toString().equals(h.photo.getTag())){h.photo.setImageBitmap(result);h.photo.setVisibility(View.VISIBLE);}});});}}else{ContactRepository.Recent c=(ContactRepository.Recent)row;String title=c.name==null||c.name.isEmpty()?context.getString(R.string.unknown_number):c.name;h.name.setText(title);h.detail.setText(c.kind()+" · "+(c.number==null?"":c.number)+"\n"+ContactRepository.dateLabel(c.date)+" · "+ContactRepository.duration(c.duration));h.avatar.setText(c.type==android.provider.CallLog.Calls.MISSED_TYPE||c.type==android.provider.CallLog.Calls.REJECTED_TYPE?"!":"↗");h.photo.setImageDrawable(null);h.photo.setVisibility(View.GONE);}h.itemView.setOnClickListener(v->{if(context instanceof androidx.fragment.app.FragmentActivity){androidx.fragment.app.FragmentActivity a=(androidx.fragment.app.FragmentActivity)context;Fragment f=a.getSupportFragmentManager().findFragmentById(R.id.content);if(f instanceof ListFragment)((ListFragment)f).rowAction(row);}});}public int getItemCount(){return rows.size();}private static String initials(String name){if(name==null||name.trim().isEmpty())return "•";String[] s=name.trim().split("\\s+");return (s[0].substring(0,1)+(s.length>1?s[s.length-1].substring(0,1):"")).toUpperCase(Locale.getDefault());}}
    private static class RowHolder extends RecyclerView.ViewHolder{TextView name,detail,avatar;ImageView photo;RowHolder(View v){super(v);name=v.findViewById(R.id.name);detail=v.findViewById(R.id.detail);avatar=v.findViewById(R.id.avatar);photo=v.findViewById(R.id.photo);}}
}
